 [[ "$(digest "$TMP/stage/$helper")" == "$expected" ]] || fail 'Dependencia alterada.'
 if [[ "${BEFORE[$helper]}" != MISSING ]];then
  existing="$(php -r '$s=file_get_contents($argv[1]);echo hash("sha256",str_replace("\r\n","\n",$s));' "$LIVE/$helper")"
  [[ "$existing" == "$expected" || "$existing" == "$previous" ]] || fail "Dependencia personalizada: $helper. No se sobrescribe."
  if [[ "$existing" == "$expected" ]];then cp -p -- "$LIVE/$helper" "$TMP/stage/$helper"
  else
   php -r '$s=file_get_contents($argv[1]);if(strpos($s,"\r\n")!==false)file_put_contents($argv[2],str_replace("\n","\r\n",file_get_contents($argv[2])));' "$LIVE/$helper" "$TMP/stage/$helper"
   chmod --reference="$LIVE/$helper" "$TMP/stage/$helper"
  fi
 else chmod 0644 "$TMP/stage/$helper";fi
