Mik7Cn0K
CORREOS_DIAGNOSTIC
 [[ "$(digest "$TMP/diagnostic.php")" == 'd347a3e4d5064e5a9833579d376f3fbe8805d8341382b57623cedae4d9e5f759' ]] || fail 'Diagnóstico de entrega alterado.'
 [[ ! -e "$LIVE/tools" || -d "$LIVE/tools" ]] || fail 'tools existe pero no es un directorio.'
 declare -A EOLS=()
 for f in "${PATCH_FILES[@]}";do
  if [[ "${BEFORE[$f]}" == MISSING ]];then
   [[ "$f" == "$DIAGNOSTIC" ]] || fail "Falta archivo requerido: $f"
   cp -- "$TMP/diagnostic.php" "$TMP/stage/$f"
  else cp -p -- "$LIVE/$f" "$TMP/stage/$f";fi
  EOLS["$f"]="$(php -r '$s=file_get_contents($argv[1]);$n=substr_count($s,"\n");$c=substr_count($s,"\r\n");if($c&&$c!==$n)exit(1);echo $c?"CRLF":"LF";file_put_contents($argv[1],str_replace("\r\n","\n",$s));' "$TMP/stage/$f")" || fail "Finales de línea mixtos: $f"
 done
 # Separar las versiones: instalación anterior -> transporte v1 -> autorización v2 -> recuperación v3.
 # Un archivo que ya contiene la actualización completa no se vuelve a parchear.
 mkdir "$TMP/base-pieces" "$TMP/upgrades" "$TMP/followups"
 php -r '$data=file_get_contents($argv[1]);$i=0;foreach(preg_split("/(?=^diff --git )/m",$data,-1,PREG_SPLIT_NO_EMPTY) as $s){if(!preg_match("/^\+\+\+ b\/(.+)$/m",$s,$m))exit(1);$at=strpos($s,"\n@@ ");if($at===false)exit(1);$head=substr($s,0,$at+1);foreach(preg_split("/(?=^@@ )/m",substr($s,$at+1),-1,PREG_SPLIT_NO_EMPTY) as $h){$p=$argv[2]."/piece_".sprintf("%03d",++$i).".patch";file_put_contents($p,$head.$h);file_put_contents($argv[2]."/manifest.tsv",$m[1]."\t".$p."\n",FILE_APPEND);}}' "$TMP/change.patch" "$TMP/base-pieces" || fail 'No se pudo preparar el parche base.'
 php -r '$data=file_get_contents($argv[1]);$i=0;foreach(preg_split("/(?=^diff --git )/m",$data,-1,PREG_SPLIT_NO_EMPTY) as $s){if(!preg_match("/^\+\+\+ b\/(.+)$/m",$s,$m))exit(1);$p=$argv[2]."/file_".sprintf("%03d",++$i).".patch";file_put_contents($p,$s);file_put_contents($argv[2]."/manifest.tsv",$m[1]."\t".$p."\n",FILE_APPEND);}' "$TMP/upgrade.patch" "$TMP/upgrades" || fail 'No se pudo preparar la actualización.'
 php -r '$data=file_get_contents($argv[1]);$i=0;foreach(preg_split("/(?=^diff --git )/m",$data,-1,PREG_SPLIT_NO_EMPTY) as $s){if(!preg_match("/^\+\+\+ b\/(.+)$/m",$s,$m))exit(1);$p=$argv[2]."/file_".sprintf("%03d",++$i).".patch";file_put_contents($p,$s);file_put_contents($argv[2]."/manifest.tsv",$m[1]."\t".$p."\n",FILE_APPEND);}' "$TMP/followup.patch" "$TMP/followups" || fail 'No se pudo preparar la corrección de recuperación.'
 declare -A READY=() FINAL=()
 while IFS=$'\t' read -r f piece;do
  [[ -n "${ALLOWED[$f]:-}" ]] || fail 'Archivo fuera de la lista aprobada.'
  if (cd "$TMP/stage" && git -c core.autocrlf=false apply --reverse --check "$piece" >/dev/null 2>&1);then FINAL["$f"]=1;READY["$f"]=1;fi
 done < "$TMP/followups/manifest.tsv"
 while IFS=$'\t' read -r f piece;do
  [[ -n "${ALLOWED[$f]:-}" ]] || fail 'Archivo fuera de la lista aprobada.'
  if (cd "$TMP/stage" && git -c core.autocrlf=false apply --reverse --check "$piece" >/dev/null 2>&1);then READY["$f"]=1;fi
 done < "$TMP/upgrades/manifest.tsv"
 while IFS=$'\t' read -r f piece;do
  [[ -n "${ALLOWED[$f]:-}" ]] || fail 'Archivo fuera de la lista aprobada.'
  [[ -z "${READY[$f]:-}" ]] || continue
  if (cd "$TMP/stage" && git -c core.autocrlf=false apply --reverse --check "$piece" >/dev/null 2>&1);then :
  else (cd "$TMP/stage" && git -c core.autocrlf=false apply --check "$piece" && git -c core.autocrlf=false apply "$piece") || fail 'Fragmento base incompatible. SITIO INTACTO.';fi
 done < "$TMP/base-pieces/manifest.tsv"
 while IFS=$'\t' read -r f piece;do
  [[ -z "${READY[$f]:-}" ]] || continue
  (cd "$TMP/stage" && git -c core.autocrlf=false apply --check "$piece" && git -c core.autocrlf=false apply "$piece") || fail 'Actualización incompatible. SITIO INTACTO.'
 done < "$TMP/upgrades/manifest.tsv"
 while IFS=$'\t' read -r f piece;do
  [[ -z "${FINAL[$f]:-}" ]] || continue
  (cd "$TMP/stage" && git -c core.autocrlf=false apply --check "$piece" && git -c core.autocrlf=false apply "$piece") || fail 'Corrección de recuperación incompatible. SITIO INTACTO.'
 done < "$TMP/followups/manifest.tsv"
 for f in "${PATCH_FILES[@]}";do
  if [[ "${EOLS[$f]}" == CRLF ]];then php -r '$p=$argv[1];file_put_contents($p,str_replace("\n","\r\n",file_get_contents($p)));' "$TMP/stage/$f";fi
  if [[ "${BEFORE[$f]}" == MISSING ]];then chmod 0644 "$TMP/stage/$f";else chmod --reference="$TMP/original/$f" "$TMP/stage/$f";fi
 done
 for f in "${FILES[@]}";do
  if [[ "$f" == *.php ]];then php -l "$TMP/stage/$f" >/dev/null || fail "Sintaxis PHP inválida: $f";fi
  AFTER["$f"]="$(digest "$TMP/stage/$f")"
  if [[ "${BEFORE[$f]}" != "${AFTER[$f]}" ]];then CHANGED+=("$f");fi
 done
fi
[[ "${#CHANGED[@]}" -gt 0 ]] || { echo 'OK: ya aplicado o restaurado. Ningún archivo reemplazado.';exit 0; }
for f in "${FILES[@]}";do unchanged "$f";done
if [[ "$MODE" == --check ]];then echo "OK: revisión compatible. ${#CHANGED[@]} archivo(s). SITIO INTACTO. Sin SQL ni envíos de correo.";exit 0;fi
if [[ "$MODE" == --apply ]];then
 mkdir -p "$BACKUPS";BACKUP="$BACKUPS/correos-multiproveedor-$(date +%Y%m%d-%H%M%S)-$$";mkdir -m 700 "$BACKUP"
 printf '%s\n' "$VERSION" > "$BACKUP/version.txt"
 if [[ ! -d "$LIVE/tools" ]];then : > "$BACKUP/tools-directory-created";fi
 for f in "${CHANGED[@]}";do
  printf '%s\t%s\t%s\n' "$f" "${BEFORE[$f]}" "${AFTER[$f]}" >> "$BACKUP/archivos.tsv"
  if [[ "${BEFORE[$f]}" != MISSING ]];then mkdir -p "$BACKUP/$(dirname "$f")";cp -p -- "$TMP/original/$f" "$BACKUP/$f";[[ "$(digest "$BACKUP/$f")" == "${BEFORE[$f]}" ]] || fail 'Respaldo inconsistente.';fi
 done
fi
WRITING=1
if [[ "$MODE" == --apply && ! -d "$LIVE/tools" ]];then no_links "$LIVE/tools";mkdir -- "$LIVE/tools";CREATED_TOOLS=1;fi
for f in "${FILES[@]}";do
 [[ -n "${AFTER[$f]:-}" && "${BEFORE[$f]}" != "${AFTER[$f]}" ]] || continue
 unchanged "$f";[[ ! -e "$LIVE/$f.impe-new-$$" && ! -L "$LIVE/$f.impe-new-$$" ]] || fail 'Existe un temporal de instalación.'
 WRITTEN+=("$f")
 if [[ "${AFTER[$f]}" == MISSING ]];then rm -- "$LIVE/$f";
 else cp -p -- "$TMP/stage/$f" "$LIVE/$f.impe-new-$$";mv -f -- "$LIVE/$f.impe-new-$$" "$LIVE/$f";[[ "$(digest "$LIVE/$f")" == "${AFTER[$f]}" ]] || fail 'Archivo instalado distinto.';fi
done
WRITING=0
if [[ "$MODE" == --restore && -f "$RESTORE/tools-directory-created" ]];then rmdir -- "$LIVE/tools" 2>/dev/null || :;fi
echo "OK: $MODE terminado. ${#CHANGED[@]} archivo(s). Sin cambios de BD ni credenciales. Verificar envíos reales por separado."
if [[ "$MODE" == --apply ]];then echo "Respaldo: $BACKUP";printf 'Rollback: bash %q --restore %q\n' "$(realpath "$0")" "$BACKUP";fi
